  vec4 n4 = texture(mNoiseTex, uv2 * mNoiseTex_ST.xy + mNoiseTex_ST.zw * custom.x + w);
  float nz = clamp(mix(1.0, dot(n4, mChannelMask2), noiseAlphaStr), 0.0, 1.0);
