  vec2 uv2 = uv * tiles + rnd * vec2(3.0, 8.0) * randomize;
  vec4 uvWarp = texture(mWarpTex, uv2 * mWarpTex_ST.xy + mWarpTex_ST.zw * (custom.x + 1.0) + vec2(5.0, 8.0) * custom.z);
  vec2 w = (uvWarp.xy * 2.0 - 1.0) * warpStr * custom.y;
  vec4 mask = vec4(1.0);
  mask = clamp(mix(vec4(1.0), mask, maskStr), 0.0, 1.0);
  vec2 t = fract(uv * tiles) - 0.5;
  t *= t * 4.0;
  float edgeMask = clamp(t.x + t.y, 0.0, 1.0);
  edgeMask = mix(1.0, 1.0 - edgeMask * edgeMask, procMask);
  mask *= edgeMask;
  vec4 vc = vColor;
  vc.a = vc.a * vc.a + alphaMin;
  vec4 c = max(vec4(0.001), vc);
  c.a = clamp(dot(mask, mChannelMask), 0.0, 1.0);
  vec4 n4 = texture(mNoiseTex, uv2 * mNoiseTex_ST.xy + mNoiseTex_ST.zw * custom.x + w);
  float nz = clamp(mix(1.0, dot(n4, mChannelMask2), noiseAlphaStr), 0.0, 1.0);
  c.a *= nz;
  float pre = c.a;
  float clipped = clamp((pre * vc.a - alphaMin) / max(alphaSoft, 1e-4), 0.0, 1.0);
  c.a = clipped;
  vec3 light = vec3(mix(1.0, 0.6, lightStr));
  vec3 nt = texture(mNormal, uv2 * mNoiseTex_ST.xy + mNoiseTex_ST.zw * custom.x + w).xyz * 2.0 - 1.0;
  nt.z = flatten * (clamp((pre * vc.a - alphaMin) / (alphaSoft + 0.2), 0.0, 1.0) - 0.1) * 1.2;
  nt = normalize(nt);
  vec3 tx = normalize(dFdx(vWorldPos) + 1e-6), ty = normalize(dFdy(vWorldPos) + 1e-6);
  vec3 nrm = normalize(normalize(vNormal) + normalize(tx * nt.x + ty * nt.y + normalize(vNormal) * nt.z));
  vec3 view = normalize(vViewDir);
  vec3 r = reflect(-view, nrm);
  r.x = atan(r.x, r.z) * 0.31831;
  r *= 0.5;
  vec2 ruv = r.xy * mReflectionTex_ST.xy + mReflectionTex_ST.zw * (uTime / 20.0 + custom.z);
  vec3 rt = texture(mReflectionTex, ruv).rgb;
  vec3 spec0 = mix(vec3(dot(rt, vec3(0.333))), rt, reflSat);
  vec3 spec = clamp(mix(spec0, spec0 * spec0 * spec0 * spec0, mSpecularColor.w * pre), 0.0, 10.0);
  spec *= clamp(1.0 - dot(view, nrm) * mSpecularColor.w, 0.2, 1.0);
  float edge = 1.0 - clamp(pre * clipped, 0.0, 1.0);
  edge = 1.0 - edge * edge;
  edge = edge + mix(0.0, nz - 0.5, noiseColorStr);
  edge = clamp(mix(0.71, edge * edge, edgeDarken), 0.0, 1.0);
  c.a *= clamp(mix(1.25, mBaseColor.a, edge), 0.0, 1.0);
  c.rgb *= mix(min(c.rgb * c.rgb * c.rgb * 0.3, vec3(1.0)), vec3(0.71), edge);
  c.rgb *= max(vec3(0.0), light * mBaseColor.rgb);
  c.rgb += light * spec * mSpecularColor.rgb;
  return c;
}
